<template>
 <main class="story-web" :class="{'is-render':renderMode,'is-reduced':reduced}" @keydown="keyControl">
  <nav v-if="!renderMode" class="story-nav" aria-label="Website navigation"><a href="#/demo/story-web" @click.prevent="scrollTime(0)" aria-label="SunnyFit story start"><img src="/assets/story/logo-on-light.svg" alt="SunnyFit" /></a><span class="story-nav-divider"></span><a href="#/demo/story-web" @click.prevent="skip">Skip story ↗</a><button class="story-motion-toggle" type="button" :aria-pressed="!reduced" @click="setMotion(reduced?'full':'reduce')">{{ reduced?'Motion: off':'Motion: on' }}</button><a class="story-download" href="#/demo/story-web" @click.prevent="skip">Get the app</a></nav>
  <section v-if="!reduced||renderMode" ref="track" class="story-track" :style="{height:renderMode?'100vh':(timelineDuration===24?'600vh':'1000vh')}" aria-label="Scroll to follow Alex’s week"><div class="story-pin" tabindex="0" aria-label="Interactive story. Scroll or use left and right arrow keys to explore."><story-stage ref="stage" :state="state"/><div v-if="!renderMode" class="story-bottom"><span>SCROLL TO EXPLORE · {{ String(state.scene).padStart(2,'0') }} / 08</span><div><i :style="{width:state.time/timelineDuration*100+'%'}"></i></div><small>Simulated V3.0 experience</small></div></div></section>
  <section v-else class="story-static" aria-label="SunnyFit story, reduced motion"><div class="story-motion-notice" role="status"><strong>You’re viewing the static story.</strong><p>{{ systemReduced&&motionChoice==='system'?'Your reduced-motion preference is on. You can choose to explore the moving story.':'Motion is turned off. You can switch back at any time.' }}</p><button type="button" @click="setMotion('full')">Enable scroll experience →</button></div><h1>A week with Alex.</h1><p>A continuous fitness journey, at your own pace.</p><article v-for="scene in visibleScenes" :key="scene.id"><span>{{ String(scene.index).padStart(2,'0') }}</span><h2>{{ scene.title }}</h2><p>{{ scene.description }}</p><div class="story-static-stage"><story-stage :state="stateAt(scene.keyStates[1].time)"/></div></article></section>
  <div v-if="!renderMode&&!reduced&&time<1.2" class="story-scroll-cue">Scroll to move through the story <span aria-hidden="true">↓</span></div>
  <section v-if="!renderMode" id="story-download" ref="footer" class="story-footer" tabindex="-1"><span class="story-eyebrow">SUNNYFIT 3.0 · EXPERIENCE PREVIEW</span><h2>Your next step starts here.</h2><p>Find your next workout, reflect on your effort, and see your week come together. At home, with the equipment you have.</p><div class="story-store-links"><a href="https://sunnyfit.com/" target="_blank" rel="noopener">Visit SunnyFit ↗</a><button disabled>App Store · link pending</button><button disabled>Google Play · link pending</button></div><p class="story-disclosure">Alex, workout records, recommendations and community reactions are simulated. This V3.0 marketing proposal illustrates a target experience; it does not confirm production availability.</p><a href="#/demo/lab?tab=components">Explore the existing Demo Lab →</a></section>
  <aside v-if="debug&&!renderMode&&!reduced" class="story-debug" aria-label="Developer timeline"><label>Time {{ state.time.toFixed(2) }} / {{ timelineDuration }} s<input aria-label="Story time" type="range" min="0" :max="timelineDuration" step="0.01" :value="state.time" @input="scrollTime(Number($event.target.value))"/></label><select aria-label="Story keyframe" @change="scrollTime(Number($event.target.value))"><option disabled selected>Jump to a key state</option><optgroup v-for="scene in visibleScenes" :key="scene.id" :label="scene.id"><option v-for="key in scene.keyStates" :key="key.id" :value="key.time">{{ key.id }} · {{ key.time }}s</option></optgroup></select><pre>{{ debugState }}</pre></aside>
 </main>
</template>
<script>
import StoryStage from '@/story/StoryStage'
const {getStoryState,clamp}=require('@/story/story-state.cjs')
const manifest=require('@/story/scene-manifest.cjs')
const {motionChoice,isReduced}=require('@/story/motion-mode.cjs')
export default {name:'StoryHome',components:{StoryStage},watch:{'$route.query.motion'(value){const mode=motionChoice(value);if(mode!==this.motionChoice){this.motionChoice=mode;this.resetPlayback()}}},data(){return {time:0,manifest,systemReduced:matchMedia('(prefers-reduced-motion: reduce)').matches,motionChoice:motionChoice(this.$route.query.motion)}},computed:{reduced(){return isReduced(this.motionChoice,this.systemReduced)},visibleScenes(){return manifest.scenes.filter(scene=>scene.start<this.timelineDuration)},timelineDuration(){return this.$route.query.review==='opening'?24:72},renderMode(){return this.$route.query.mode==='render'},debug(){return this.$route.query.debug==='1'},state(){return getStoryState(this.time)},debugState(){return JSON.stringify({scene:this.state.sceneId,date:this.state.date,completed:this.state.records.map(r=>r.id),totals:this.state.totals,result:this.state.session},null,2)}},
 mounted(){this.previousTitle=document.title;document.title='SunnyFit 3.0 — A week with Alex';this.motionQuery=matchMedia('(prefers-reduced-motion: reduce)');this.systemReduced=this.motionQuery.matches;this.motionQuery.addEventListener('change',this.motionChange);this.oldScroll=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';window.addEventListener('scroll',this.onScroll,{passive:true});window.addEventListener('resize',this.onScroll);this.meta=document.createElement('meta');this.meta.name='description';this.meta.content='Follow a week of at-home fitness with SunnyFit 3.0: direction, guidance and progress. An interactive simulated experience.';document.head.appendChild(this.meta);this.og=[];for(const [property,content] of Object.entries({'og:title':document.title,'og:description':this.meta.content,'og:type':'website','og:image':location.origin+'/assets/story/home-gym.png'})){const tag=document.createElement('meta');tag.setAttribute('property',property);tag.content=content;document.head.appendChild(tag);this.og.push(tag)};
 const ready=this.$nextTick().then(async()=>{await document.fonts.ready;await Promise.all([...this.$el.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(this.renderMode)await this.seekTime(Number(this.$route.query.frame||0)/Number(this.$route.query.fps||30));else this.onScroll()})
 this.api={ready,seekProgress:p=>this.seekTime(clamp(Number(p))*72),seekTime:t=>this.seekTime(t),getState:()=>JSON.parse(JSON.stringify(this.state)),getManifest:()=>manifest,getPlayback:()=>({mode:this.reduced?'static':'scroll',choice:this.motionChoice,systemReduced:this.systemReduced})};window.__SUNNYFIT_STORY__=this.api
 },beforeDestroy(){window.removeEventListener('scroll',this.onScroll);window.removeEventListener('resize',this.onScroll);this.motionQuery.removeEventListener('change',this.motionChange);document.documentElement.style.scrollBehavior=this.oldScroll;if(this.meta)this.meta.remove();if(this.og)this.og.forEach(tag=>tag.remove());if(window.__SUNNYFIT_STORY__===this.api)delete window.__SUNNYFIT_STORY__;document.title=this.previousTitle},methods:{stateAt:getStoryState,async resetPlayback(){this.time=0;await this.$nextTick();window.scrollTo(0,0);this.onScroll()},async setMotion(mode){this.motionChoice=motionChoice(mode);await this.$router.replace({path:this.$route.path,query:{...this.$route.query,motion:this.motionChoice}}).catch(error=>{if(error.name!=='NavigationDuplicated')throw error});await this.resetPlayback();if(!this.reduced&&this.$refs.track)this.$refs.track.querySelector('.story-pin').focus({preventScroll:true})},motionChange(e){this.systemReduced=e.matches;if(this.motionChoice==='system')this.resetPlayback()},onScroll(){if(this.renderMode||this.reduced||!this.$refs.track)return;const rect=this.$refs.track.getBoundingClientRect();this.time=clamp(-rect.top/(rect.height-window.innerHeight))*this.timelineDuration},async seekTime(t){this.time=clamp(Number(t),0,72);await this.$nextTick();await new Promise(resolve=>requestAnimationFrame(resolve));return this.state},scrollTime(t){if(this.renderMode)return this.seekTime(t);if(!this.$refs.track)return;const top=this.$refs.track.getBoundingClientRect().top+window.scrollY;window.scrollTo({top:top+clamp(t/this.timelineDuration)*(this.$refs.track.offsetHeight-window.innerHeight),behavior:'instant'});this.onScroll()},skip(){this.$refs.footer.scrollIntoView({behavior:'instant'});this.$refs.footer.focus()},keyControl(e){if(['INPUT','SELECT','BUTTON','A'].includes(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();this.scrollTime(this.time+(e.key==='ArrowRight'?1:-1))}if(e.key==='Home'){e.preventDefault();this.scrollTime(0)}if(e.key==='End'){e.preventDefault();this.skip()}}}}
</script>
<style>
.story-web{background:#f7f6f3;color:#292923;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif}.story-nav{position:fixed;z-index:50;top:22px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:24px;padding:12px 14px 12px 22px;border:1px solid #ffffffb8;border-radius:100px;background:#ffffff9c;backdrop-filter:blur(24px) saturate(140%);box-shadow:inset 0 1px 1px #fff,0 6px 28px #27231b14;color:#302f2c;white-space:nowrap;font-size:12px}.story-nav img{display:block;width:118px;height:auto}.story-nav-divider{height:18px;width:1px;background:#29292325}.story-nav .story-download{background:#252822;color:#fff;border-radius:100px;padding:11px 20px}.story-nav a:focus-visible,.story-footer a:focus-visible{outline:3px solid #e81d1d;outline-offset:5px}.story-pin{position:sticky;top:0;height:100vh;outline:none}.story-bottom{position:absolute;bottom:24px;left:5%;right:5%;display:flex;align-items:center;gap:24px;z-index:30;font-size:9px;letter-spacing:.08em;color:#5f5d56}.story-bottom>div{width:140px;height:2px;background:#9b958e44}.story-bottom i{height:100%;display:block;background:#e81d1d}.story-bottom small{margin-left:auto;font-size:9px}.story-footer{max-width:920px;margin:auto;padding:120px 32px;outline:none}.story-footer h2{font-size:clamp(34px,4vw,60px);letter-spacing:-.05em;font-weight:500;line-height:1.1}.story-footer p{font-size:18px;line-height:1.7;color:#716d66;max-width:680px}.story-store-links{display:flex;gap:12px;flex-wrap:wrap;margin:34px 0}.story-store-links a,.story-store-links button{padding:15px 20px;border-radius:100px;border:1px solid #29292333;font-size:13px;background:transparent;color:#74726b}.story-store-links a{background:#e81d1d;color:white;border-color:#e81d1d}.story-store-links button:disabled{cursor:not-allowed}.story-footer .story-disclosure{font-size:12px;margin-bottom:35px}.story-debug{position:fixed;left:12px;bottom:55px;z-index:60;width:245px;padding:12px;background:#20241fef;color:#fff;border-radius:12px;font:11px monospace;box-shadow:0 2px 15px #0002}.story-debug input{display:block;width:100%;margin:10px 0}.story-debug select{width:100%}.story-debug pre{max-height:190px;overflow:auto;white-space:pre-wrap;font-size:10px}.story-static{padding:100px 24px 0;max-width:1000px;margin:auto}.story-static>h1{font-size:42px;letter-spacing:-.05em}.story-static article{margin:70px 0}.story-static article>span{color:#e81d1d;font-size:12px}.story-static article>h2{font-size:28px}.story-static-stage{height:780px;border-radius:24px;overflow:hidden}.story-static .story-copy{display:none}.is-render .story-track,.is-render .story-pin{height:100vh}.is-render{cursor:none}.is-render *{cursor:none!important}.story-web .story-stage{--sf-font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif}
@media(max-width:759px){.story-nav{top:14px;gap:12px;padding:8px 9px 8px 16px;max-width:calc(100% - 28px);font-size:10px}.story-nav img{width:96px}.story-nav .story-download{padding:10px 12px}.story-nav-divider{display:none}.story-bottom{bottom:16px;gap:10px;font-size:8px}.story-bottom>div{width:65px}.story-bottom small{font-size:7px;max-width:90px;text-align:right}.story-static-stage{height:720px}.story-footer{padding:80px 24px}.story-debug{width:190px;opacity:.92}.story-debug pre{max-height:90px}}
@media(prefers-reduced-transparency:reduce){.story-nav{background:#f6f5f2;backdrop-filter:none}}
@media(min-width:760px){.story-nav{left:28px;transform:none;top:22px}}
.story-motion-toggle{border:0;border-radius:18px;padding:8px 10px;background:#ffffff90;color:#292923;font:inherit;cursor:pointer;min-height:36px}.story-motion-toggle:focus-visible,.story-motion-notice button:focus-visible{outline:3px solid #e81d1d;outline-offset:3px}
.story-motion-notice{padding:24px;background:#fff;border:1px solid #e5e5e5;border-radius:20px;margin-top:30px}.story-motion-notice strong{font-size:20px}.story-motion-notice p{font-size:15px;line-height:1.6;color:#666}.story-motion-notice button{border:0;background:#e81d1d;color:#fff;padding:13px 20px;border-radius:24px;font-size:14px;cursor:pointer}
.story-scroll-cue{position:fixed;left:50%;bottom:74px;transform:translateX(-50%);display:flex;align-items:center;gap:18px;z-index:35;padding:13px 20px;border:1px solid #fff8;border-radius:28px;background:#fffe;color:#222;box-shadow:0 4px 20px #0001;font-size:14px;white-space:nowrap;pointer-events:none}.story-scroll-cue span{font-size:20px}
@media(max-width:759px){.story-nav{gap:8px;padding:8px 10px}.story-nav img{width:83px}.story-motion-toggle{padding:6px 7px;min-height:32px;font-size:9px}.story-nav .story-download{padding:9px 10px}.story-scroll-cue{font-size:12px;bottom:66px;gap:12px;padding:10px 16px}.story-motion-notice{margin-top:12px}}
</style>
